(()=>{'use strict';
const el=id=>document.getElementById(id),library=window.OPENING_LIBRARY,Chess=window.Chess;
const studyIds=[...new Set(library.map(x=>x.studyId||x.id))];
let study=library[0],labels=[];
function variationCount(n){return n+' '+(n%100>=11&&n%100<=14?'вариантов':n%10===1?'вариант':n%10>=2&&n%10<=4?'варианта':'вариантов')}
function option(select,value,label){const opt=document.createElement('option');opt.value=value;opt.textContent=label;select.append(opt)}
function makeLabels(chapter){return chapter.lines.map((line,i)=>{if(i===0)return 'Основная линия';const main=chapter.lines[0];const p=line.findIndex((m,n)=>!main[n]||m.san!==main[n].san);const n=p<0?0:p;return 'Вариант '+(i+1)+' · '+(Math.floor(n/2)+1)+(n%2?'...':'.')+line[n].san})}
function populateLines(){labels=makeLabels(study);el('openingLine').replaceChildren(document.createDocumentFragment());option(el('openingLine'),'all','Все варианты · каждый с начала');study.lines.forEach((line,i)=>option(el('openingLine'),String(i),labels[i]+' · '+Math.ceil(line.length/2)+' ходов'));el('openingLine').value='all'}
function populateChapters(id){el('openingChapter').replaceChildren(document.createDocumentFragment());library.filter(x=>(x.studyId||x.id)===id).forEach(x=>option(el('openingChapter'),x.id,x.chapter+' · '+variationCount(x.lines.length)));study=library.find(x=>(x.studyId||x.id)===id);el('openingChapter').value=study.id;populateLines()}
studyIds.forEach(id=>option(el('openingStudy'),id,library.find(x=>(x.studyId||x.id)===id).title));el('openingStudy').value=studyIds[studyIds.length-1];populateChapters(el('openingStudy').value);
let bothSides=false,studying=false;
const isUserTurn=()=>bothSides||game.turn()===el('openingSide').value;
let lineIndices=[],lineCursor=0,activeLineIndex=0,waitingForNext=false;
let game=new Chess(),line=[],ply=0,selected=null,running=false,errors=0,hints=0,answers=[],startedAt=null,turnStart=0,timer=null,generation=0,lastMove=null,visible=false,history=[];
try{const saved=JSON.parse(localStorage.getItem('chess-openings-v1'));if(Array.isArray(saved))history=saved}catch{}
const fmt=s=>new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',dateStyle:'short',timeStyle:'medium'}).format(new Date(s));
const pieces={k:'♚',q:'♛',r:'♜',b:'♝',n:'♞',p:'♟'};
function renderBoard(){const side=el('openingSide').value,frag=document.createDocumentFragment();for(let r=0;r<8;r++)for(let c=0;c<8;c++){const f=side==='w'?c:7-c,rank=side==='w'?8-r:r+1,sq='abcdefgh'[f]+rank,piece=game.get(sq),b=document.createElement('button');b.className='sq'+((f+rank)%2===1?' dark':'')+(piece?.color==='w'?' piece-white':'')+(selected===sq?' selected':'')+((lastMove&&(lastMove.from===sq||lastMove.to===sq))?' lastmove':'');b.textContent=piece?pieces[piece.type]:'';b.setAttribute('aria-label',sq+(piece?' '+(piece.color==='w'?'белая ':'чёрная ')+({p:'пешка',n:'конь',b:'слон',r:'ладья',q:'ферзь',k:'король'})[piece.type]:''));b.onclick=()=>clickSquare(sq);frag.append(b)}el('openingBoard').replaceChildren(frag)}
function render(){renderBoard();const chapters=library.filter(x=>(x.studyId||x.id)===(study.studyId||study.id));el('openingTitle').textContent=study.title;el('openingLibraryCount').textContent='БИБЛИОТЕКА ДЕБЮТОВ · '+studyIds.length+' СТУДИИ';el('openingChapterInfo').textContent=study.chapter+' · '+variationCount(study.lines.length);el('openingCurrentChapter').textContent=study.title+' → '+study.chapter+' ('+(chapters.indexOf(study)+1)+' из '+chapters.length+')';el('openingSource').href=study.url;el('openingPgn').href=study.pgn;el('openingHint').textContent='Все варианты выбранной главы проходят по очереди, каждый с исходной позиции. Тренажёр проверяет ходы по студии; при ошибке попробуйте ещё раз.';const side=el('openingSide').value,total=bothSides?line.length:line.filter((_,i)=>i%2===(side==='w'?0:1)).length;el('openingCount').textContent=answers.filter(x=>x.correct).length+' / '+total;el('openingErrors').textContent=errors;el('openingStudyMode').setAttribute('aria-pressed',String(studying));el('openingStudyMode').classList.toggle('primary',studying);el('openingStudyMode').textContent=studying?'Изучение: включено':'Изучение';el('openingStepControls').hidden=!studying;el('openingBack').disabled=!studying||ply===0;el('openingForward').disabled=!studying||ply>=line.length;el('openingBoth').disabled=studying;el('openingHelp').disabled=!running||!isUserTurn();el('openingBoth').setAttribute('aria-pressed',String(bothSides));el('openingBoth').textContent=bothSides?'За обе стороны: включено':'За обе стороны';el('openingBoth').classList.toggle('primary',bothSides);el('openingSideLabel').textContent=bothSides||studying?'Ориентация доски':'Я играю за';el('openingLine').disabled=!studying&&(running||waitingForNext);el('openingSide').disabled=!studying&&(running||waitingForNext);el('openingStart').textContent=running||waitingForNext?'Начать заново':(el('openingLine').value==='all'?'Начать все варианты':'Начать вариант');el('openingRepeat').disabled=lineIndices.length===0;el('openingNext').hidden=!waitingForNext;el('openingSequence').textContent=lineIndices.length>1?'Вариант '+(lineCursor+1)+' из '+lineIndices.length+' · '+labels[activeLineIndex]:labels[activeLineIndex];el('openingMoves').textContent=game.history().map((m,i)=>(i%2===0?Math.floor(i/2)+1+'. ':'')+m).join(' ')||'—';el('openingDates').textContent=startedAt?'Начало: '+fmt(startedAt)+' · МСК':'';if(studying){el('openingStatus').textContent='Изучение · '+ply+' / '+line.length+' ходов';el('openingHint').textContent='Листайте ходы белых и чёрных кнопками. Каждое нажатие — один ход одной стороны. Просмотр не записывается как тренировка.';el('openingFeedback').textContent=ply?'Показан ход: '+(Math.floor((ply-1)/2)+1)+(ply%2?'. ':'... ')+line[ply-1].san:'Исходная позиция';el('openingStart').textContent='С начала всей очереди'}el('openingExport').value=report();}
function schedule(){clearTimeout(timer);if(!running||!visible||document.hidden)return;if(ply>=line.length){finish();return}if(isUserTurn()){turnStart=performance.now();el('openingStatus').textContent='Ваш ход · '+(game.turn()==='w'?'белые':'чёрные');render();return}el('openingStatus').textContent='Ход соперника…';render();const g=generation;timer=setTimeout(()=>{if(g!==generation||!running||!visible)return;lastMove=game.move(line[ply].san);ply++;render();schedule()},550)}
function resetChapter(){generation++;clearTimeout(timer);running=false;waitingForNext=false;lineIndices=[];lineCursor=0;activeLineIndex=0;line=[];ply=0;selected=null;game=new Chess();errors=0;hints=0;answers=[];startedAt=null;lastMove=null;el('openingStatus').textContent='Готовы начать?';el('openingFeedback').textContent='';render()}
el('openingStudy').onchange=()=>{populateChapters(el('openingStudy').value);resetChapter();if(studying)start()};el('openingChapter').onchange=()=>{study=library.find(x=>x.id===el('openingChapter').value);populateLines();resetChapter();if(studying)start()};
function start(){lineIndices=el('openingLine').value==='all'?study.lines.map((_,i)=>i):[Number(el('openingLine').value)];lineCursor=0;beginLine()}
function beginLine(){waitingForNext=false;activeLineIndex=lineIndices[lineCursor];generation++;clearTimeout(timer);game=new Chess();line=study.lines[activeLineIndex];ply=0;selected=null;running=!studying;errors=0;hints=0;answers=[];startedAt=studying?null:new Date().toISOString();lastMove=null;el('openingFeedback').textContent='';render();schedule()}
function clickSquare(sq){if(!running||!isUserTurn()||!visible)return;const piece=game.get(sq);if(piece&&piece.color===game.turn()){selected=selected===sq?null:sq;renderBoard();return}if(!selected)return;const from=selected,expected=line[ply];selected=null;let move;try{const probe=new Chess(game.fen());move=probe.move({from,to:sq,promotion:'q'})}catch{}if(!move){el('openingFeedback').textContent='Такой ход невозможен. Выберите фигуру и клетку ещё раз.';renderBoard();return}const correct=move.from===expected.from&&move.to===expected.to&&move.promotion===expected.promotion;answers.push({ply:ply+1,side:game.turn(),played:move.san,expected:expected.san,correct,ms:Math.round(performance.now()-turnStart),answeredAt:new Date().toISOString()});if(!correct){errors++;el('openingFeedback').textContent='В выбранном варианте другой ход. Попробуйте ещё раз или откройте подсказку.';turnStart=performance.now();render();return}lastMove=game.move(expected.san);ply++;el('openingFeedback').textContent='Верно: '+move.san;render();schedule()}
function finish(){running=false;waitingForNext=lineCursor+1<lineIndices.length;el('openingStatus').textContent=waitingForNext?'Вариант пройден':(lineIndices.length>1?'Все варианты пройдены':'Вариант пройден');el('openingFeedback').textContent='Все ходы сыграны. '+(errors?'Ошибок: '+errors+'. Повторите вариант позже.':'Без ошибок! Повторите позже для закрепления.');history.push({studyId:study.studyId||study.id,chapterId:study.id,chapter:study.chapter,sourceUrl:study.url,title:study.title,line:labels[activeLineIndex],mode:lineIndices.length>1?'all':'single',sequenceNumber:lineCursor+1,sequenceTotal:lineIndices.length,side:bothSides?'both':el('openingSide').value,orientation:el('openingSide').value,startedAt,completedAt:new Date().toISOString(),errors,hints,answers});try{localStorage.setItem('chess-openings-v1',JSON.stringify(history))}catch{el('openingFeedback').textContent+=' Сохранение недоступно — скопируйте результаты.'}render()}
function report(){const lines=['Тренировка дебютов. Время: МСК (Europe/Moscow).',study.title+' · '+study.chapter,study.url];for(const h of history){const chapter=h.chapter||library.find(x=>x.id===(h.chapterId||h.studyId))?.chapter||'Глава не записана';lines.push('\n'+h.title+' · '+chapter+'\n'+h.line+'; игра за '+(h.side==='both'?'обе стороны':h.side==='w'?'белых':'чёрных')+'.','Начало: '+fmt(h.startedAt)+'; завершение: '+fmt(h.completedAt)+'.',`Ошибок: ${h.errors}; подсказок: ${h.hints}.`);for(const a of h.answers)lines.push(`${a.ply}: ${a.played} — ${a.correct?'верно':'ошибка; ожидалось '+a.expected}, ${(a.ms/1000).toFixed(2)} с.`)}if(running)lines.push('\nТекущий вариант не завершён.');lines.push('\nПроанализируй ошибки и запоминание вариантов.');return lines.join('\n')}
el('openingStudyMode').onclick=()=>{studying=!studying;if(lineIndices.length)beginLine();else start()};el('openingForward').onclick=()=>{if(!studying||ply>=line.length)return;lastMove=game.move(line[ply].san);ply++;waitingForNext=ply===line.length&&lineCursor+1<lineIndices.length;render()};el('openingBack').onclick=()=>{if(!studying||ply===0)return;game.undo();ply--;selected=null;lastMove=game.history({verbose:true}).at(-1)||null;waitingForNext=false;render()};
el('openingHelp').onclick=()=>{if(!running||!isUserTurn())return;hints++;const m=line[ply];el('openingFeedback').textContent='Ход по варианту: '+m.san+' ('+m.from+' → '+m.to+').';render()};el('openingBoth').onclick=()=>{bothSides=!bothSides;if(running||waitingForNext)start();else render()};el('openingRepeat').onclick=()=>{if(lineIndices.length)beginLine()};el('openingStart').onclick=start;el('openingNext').onclick=()=>{if(waitingForNext){lineCursor++;beginLine()}};el('openingSide').onchange=renderBoard;el('openingLine').onchange=()=>{lineIndices=[];lineCursor=0;activeLineIndex=el('openingLine').value==='all'?0:Number(el('openingLine').value);if(studying)start();else render()};
el('openingCopy').onclick=async()=>{try{await navigator.clipboard.writeText(report());el('openingCopy').textContent='Скопировано — вставьте в чат'}catch{el('openingExport').focus();el('openingExport').select();el('openingCopy').textContent='Текст выделен — скопируйте'}};
function tab(open){visible=open;el('coordsView').hidden=open;el('openingsView').hidden=!open;el('coordsTab').setAttribute('aria-selected',String(!open));el('openingsTab').setAttribute('aria-selected',String(open));generation++;clearTimeout(timer);if(open){if(typeof pauseOnHide==='function')pauseOnHide();render();schedule()}}
el('coordsTab').onclick=()=>tab(false);el('openingsTab').onclick=()=>tab(true);document.addEventListener('visibilitychange',()=>{generation++;clearTimeout(timer);if(!document.hidden&&visible)schedule()});render();
})();
